import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(address impl, address settingsAddr, bytes memory encodedParameters, address ownedBy) internal {
        bool beforeNotOperator = c.programOperators(address(this)) == false;
        bool reverted;
        address result;
        try c.create(encodedParameters, ownedBy) returns (address created) {
            result = created;
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(beforeNotOperator && reverted && result == address(0));
    }

